unsigned process_audio_data(SF_PRIVATE* psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned buffer_pos = 0;

    if (psf == NULL || len == 0) {
        return 0;
    }

    // Initialize position and remaining length for reading
    buffer_pos = psf->frame_buffer_pos;
    remaining = len;

    // If a frame is available and not fully processed, copy the buffered data
    if (buffer_pos > 0) {
        unsigned copy_len = (buffer_pos < remaining) ? buffer_pos : remaining;
        memcpy(psf->output_buffer + bytes_read, psf->frame_buffer, copy_len);
        bytes_read += copy_len;
        remaining -= copy_len;
        psf->frame_buffer_pos -= copy_len;
        memmove(psf->frame_buffer, psf->frame_buffer + copy_len, psf->frame_buffer_pos);
    }

    // Enter loop to decode audio data until specified length is reached or end-of-stream
    while (remaining > 0 && !psf->eof_reached) {
        unsigned decoded = decode_audio_frame(psf, psf->output_buffer + bytes_read, remaining);
        if (decoded == 0) {
            psf->eof_reached = 1;
            break;
        }
        bytes_read += decoded;
        remaining -= decoded;
    }

    return bytes_read;
}
